updateRule:
id = @request.auth.id && 
@request.body.isCompany:changed = false && 
@request.body.name:changed = false &&
@request.body.locked:changed = false &&
@request.body._hidden:changed = false &&
@request.body.verified:changed = false &&
@request.body.mfaRequired:changed = false &&
@request.body.data:changed = false

@request.auth.id = account.user.id &&
@request.body.security:changed = false &&
@request.body.checksum:changed = false &&
@request.body.account:changed = false &&
@request.body.frozen:changed = false &&
@request.body.number:changed = false

(@request.auth.data.financeTrackingAccess = true) && @request.body.sender:changed = false &&
@request.body.receiver:changed = false && 
@request.body.amount:changed = false &&
@request.body.received:changed = false && 
@request.body.description:changed = false && 
@request.body.system:changed = false && 
@request.body.signature:changed = false

(@request.auth.id = user.id &&
@request.body.user:changed = false &&
@request.body.registered:changed = false &&
@request.body.warehouseAccess:changed = false &&
@request.body.financeTrackingAccess:changed = false &&
@request.body.euroSpent:changed = false &&
@request.body.euroAvailable:changed = false)
||
(@request.auth.data.warehouseAccess = true &&
@request.body.user:changed = false &&
@request.body.firstTimeLogin:changed = false &&
@request.body.registered:changed = false &&
@request.body.financeTrackingAccess:changed = false &&
@request.body.warehouseAccess:changed = false)
||
(@request.auth.data.financeTrackingAccess= true &&
@request.body.user:changed = false &&
@request.body.financeTrackingAccess:changed = false &&
@request.body.warehouseAccess:changed = false &&
@request.body.euroSpent:changed = false &&
@request.body.euroAvailable:changed = false)
